188	  if (Number(request.headers.get("content-length") ?? 0) > MAX_BODY_BYTES) return done(413);
189	
190	  // 2-3. Raw body, read once; no request.json() and no JSON.parse before the signature
191	  const raw = await request.text();
192	  if (Buffer.byteLength(raw) > MAX_BODY_BYTES) return done(413);
193	
194	  // 4. Timestamp window, both directions
195	  const timestamp = request.headers.get("x-n8n-timestamp") ?? "";
