"use server";

import { randomUUID } from "node:crypto";
import { after } from "next/server";
import { redirect } from "next/navigation";
import { db } from "@/lib/db";
import { triggerWorkflow } from "@/lib/n8n/client";
import { parseQuoteForm, type QuoteFormField, type QuoteFormValues } from "@/lib/quote-form";

export type RequestQuoteState =
  | { status: "idle" }
  | { status: "invalid"; errors: Partial<Record<QuoteFormField, string>>; values: QuoteFormValues };

export async function requestQuote(
  _prevState: RequestQuoteState,
  formData: FormData,
): Promise<RequestQuoteState> {
  // Public form, like the lead form: no session on purpose. Validation happens here, not only in the UI.
  const parsed = parseQuoteForm(formData);
  if (!parsed.ok) {
    return { status: "invalid", errors: parsed.errors, values: parsed.values };
  }

  const quote = await db.insertQuote({
    ...parsed.data,
    id: randomUUID(),
    status: "queued",
    requestKey: randomUUID(),
    correlationId: randomUUID(),
  });

  // The quote-request workflow takes 40-90 s: the user never waits for n8n.
  // n8n answers 202 right away and later calls /api/n8n/quote-request.
  after(async () => {
    let ok = false;
    try {
      const result = await triggerWorkflow(
        "quote-request",
        // Only what the workflow needs to build the quote: no email, IP or other personal data.
        { quoteId: quote.id, company: quote.company, description: quote.description, budget: quote.budget },
        { idempotencyKey: quote.requestKey, correlationId: quote.correlationId, callback: true },
      );
      ok = result.ok;
    } catch {
      // Misconfiguration (missing N8N_* variables): the quote is marked failed below.
      console.error(JSON.stringify({ n8n: "out", event: "quote-request", correlationId: quote.correlationId, status: "config-error" }));
    }
    // Only if still queued: a fast workflow may already have set "ready" via the callback.
    if ((await db.getQuote(quote.id))?.status === "queued") {
      await db.updateQuote(quote.id, { status: ok ? "sent" : "failed" });
    }
  });

  redirect(`/quotes/${quote.id}`);
}

