import Link from "next/link";
import { notFound } from "next/navigation";
import { QuoteStatusRefresh } from "@/components/quote-status-refresh";
import { db } from "@/lib/db";
import type { QuoteStatus } from "@/lib/types";

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

const dateTimeFormat = new Intl.DateTimeFormat("uk-UA", { dateStyle: "medium", timeStyle: "short" });
const usd = new Intl.NumberFormat("uk-UA", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

const STATUS_VIEW: Record<QuoteStatus, { label: string; text: string; className: string }> = {
  queued: {
    label: "Готуємо",
    text: "Запит прийнято, кошторис готується. Зазвичай це займає одну-дві хвилини — сторінка оновиться сама.",
    className: "bg-sky-50 text-sky-700 ring-sky-200",
  },
  sent: {
    label: "Готуємо",
    text: "Запит прийнято, кошторис готується. Зазвичай це займає одну-дві хвилини — сторінка оновиться сама.",
    className: "bg-sky-50 text-sky-700 ring-sky-200",
  },
  ready: {
    label: "Готово",
    text: "Кошторис готовий.",
    className: "bg-emerald-50 text-emerald-700 ring-emerald-200",
  },
  failed: {
    label: "Не вдалося",
    text: "Не вдалося підготувати кошторис. Спробуйте надіслати запит ще раз або напишіть нам.",
    className: "bg-red-50 text-red-700 ring-red-200",
  },
};

// Public page: the unguessable UUID is the only access check, so it shows no email and no internal ids.
export default async function QuotePage({ params }: PageProps<"/quotes/[id]">) {
  const { id } = await params;
  if (!UUID_RE.test(id)) notFound();
  const quote = await db.getQuote(id);
  if (!quote) notFound();

  const view = STATUS_VIEW[quote.status];
  const pending = quote.status === "queued" || quote.status === "sent";

  return (
    <main className="mx-auto w-full max-w-2xl flex-1 space-y-6 px-6 py-12">
      <Link href="/" className="text-sm text-slate-500 hover:text-slate-900">
        ← Studio Nova
      </Link>

      <div className="flex items-start justify-between gap-4">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight">Кошторис для {quote.company}</h1>
          <p className="text-sm text-slate-500">Запит від {dateTimeFormat.format(new Date(quote.createdAt))}</p>
        </div>
        <span
          className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium ring-1 ring-inset ${view.className}`}
          role="status"
        >
          {view.label}
        </span>
      </div>

      <section className="space-y-4 rounded-lg border border-slate-200 bg-white p-5 text-sm">
        <p className="text-slate-700">{view.text}</p>
        {quote.status === "ready" && quote.documentUrl && (
          <a
            href={quote.documentUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex rounded-md bg-indigo-600 px-4 py-2 font-medium text-white hover:bg-indigo-700"
          >
            Відкрити кошторис (PDF)
          </a>
        )}
        {quote.status === "failed" && (
          <Link href="/quotes/new" className="inline-flex text-indigo-600 hover:text-indigo-800">
            Надіслати новий запит →
          </Link>
        )}
      </section>

      <dl className="grid grid-cols-1 gap-x-6 gap-y-3 rounded-lg border border-slate-200 bg-white p-5 text-sm sm:grid-cols-2">
        <div>
          <dt className="text-slate-500">Бюджет</dt>
          <dd className="font-medium">{quote.budget === null ? "—" : usd.format(quote.budget)}</dd>
        </div>
        <div className="sm:col-span-2">
          <dt className="text-slate-500">Опис задачі</dt>
          <dd className="whitespace-pre-line break-words text-slate-700">{quote.description}</dd>
        </div>
      </dl>

      {pending && <QuoteStatusRefresh />}
    </main>
  );
}

